#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [-0.12694633, -0.37112958500000004, 0.0035348550000000034], 'basis': [[0.5527289219097434, -0.05608223141891469, 0.8314719010306771], [0.0, 0.9977330253570025, 0.06729643461553471], [-0.833361109534452, -0.03719668575341403, 0.5514758994593227]], 'axis': [0.8314719010306771, 0.06729643461553471, 0.5514758994593227], 'zmin': -0.05140379900326069, 'zmax': 0.04440531483516556, 'profiles': [{'outer': [[-0.10502898761821933, -0.049968723534644315], [-0.10488042531339431, -0.048034264435661715], [-0.1045125908093056, -0.0454641337639975], [-0.10376973787318862, -0.04195011133154221], [-0.10258834317415706, -0.0373174149412517], [-0.1008833844054944, -0.031740394086133675], [-0.09866202330062877, -0.025501323289757887], [-0.09588888684195776, -0.018880688307485845], [-0.09255682715695347, -0.01213047052998036], [-0.08858107020643653, -0.005558530464770879], [-0.08320384806266949, 0.0014838359169259505], [-0.07803476221111894, 0.006568666347111476], [-0.07165173293812711, 0.011088589871941485], [-0.06364747207734307, 0.014984296579258812], [-0.0539534022273251, 0.01783644756404654], [-0.04276761988154358, 0.01916324893953476], [-0.042272169881040496, 0.019209122734699824], [-0.03009713666503749, 0.01874806165058531], [-0.01790053037079402, 0.017564650686476748], [-0.006402383166370714, 0.01691960221948269], [0.002697710094885786, 0.018419044137362037], [0.005031680605526027, 0.020377605474528306], [0.008215546337618342, 0.023318705353456304], [0.00933589291713294, 0.02613872386170995], [0.010739853991818215, 0.03004464282545702], [0.011606362449136712, 0.03656059541967485], [0.011754927474929077, 0.04299927885869915], [0.011776186516833303, 0.04793706064227047], [0.012052060332835688, 0.05142332517483745], [0.012177337424809578, 0.05234468722974721], [0.012924276532875598, 0.05450215940392207], [0.014301739022207318, 0.05576943497011316], [0.014674854247159324, 0.055990765313302264], [0.016475619557076538, 0.056594866835410956], [0.019485173448520337, 0.05709106955925438], [0.0232076273326529, 0.057288363913786985], [0.031569742089121125, 0.05733488966327451], [0.05778720907832163, 0.05735093176016052], [0.06690475015954363, 0.0571768811878832], [0.07503739981086366, 0.056702231298486], [0.08122543568123751, 0.055891622651461935], [0.08499103858755665, 0.05463343495121192], [0.08659482046099194, 0.05387381283252832], [0.08874549097425391, 0.05156347431102859], [0.0895377782663922, 0.048077516118127314], [0.08965098413548243, 0.04314164683328939], [0.08974294762989063, 0.020773236172314326], [0.08985616463891383, 0.012554676878854096], [0.09005419726981735, 0.00474085739266851], [0.09045023208885641, -0.002667265476214424], [0.09115012874136823, -0.009779167822981029], [0.0923024385629539, -0.016696081646899792], [0.09394949786806439, -0.02349875763501905], [0.0958509459596018, -0.029926821821378707], [0.0992649690570657, -0.04048744492970464], [0.10023337399899186, -0.04409609878962351], [0.10074935760894216, -0.04670375411406034], [0.10094021753719358, -0.04864165675132227], [0.10097556836028462, -0.05019441193440953], [0.10081290874698356, -0.051567571533030626], [0.09980848870914381, -0.0527865557475361], [0.098034181666385, -0.05405914637891133], [0.09556253480669105, -0.0549057909304957], [0.09096375916238002, -0.055832723919227], [0.08873092996953703, -0.056093987058024465], [0.08281051193565642, -0.05661292451870366], [0.07414321249806868, -0.056916446235074435], [0.06544862539296312, -0.05681242306588516], [0.0594451947522013, -0.05646858192240996], [0.052434140020960744, -0.055556777713660944], [0.04956621549490692, -0.054801792060636866], [0.04747713400005038, -0.053899199101992326], [0.04491547162690202, -0.053034268044577136], [0.0424252190999749, -0.052664779304783915], [0.03731235023097782, -0.0524767799924877], [0.032868533967592956, -0.0526692797391725], [0.029478505864491494, -0.053236185616655586], [0.028053076593539457, -0.05392320770027963], [0.026930901399384984, -0.054867623871297316], [0.0258803069719734, -0.055635566730442135], [0.024851077498259783, -0.05628762437269732], [0.024101545609961507, -0.05661240929992866], [0.02230436944499141, -0.05700260539481517], [0.01871876937357118, -0.057331818512797936], [0.013084856176019673, -0.057469448975659886], [0.005160635662220196, -0.05753547183397038], [-0.045587771573262305, -0.05773691137679955], [-0.06033791686528936, -0.05773960588312895], [-0.07392530861205075, -0.05764229560848601], [-0.08482760315527729, -0.057327406278042434], [-0.09150491832626235, -0.056934490241970136], [-0.09897078084801121, -0.055929456763163944], [-0.101570210945551, -0.055081274368501826], [-0.10384760678008809, -0.05408999683735711], [-0.10490169268890963, -0.05287022793596219], [-0.10505024666012355, -0.051496523225462186]], 'holes': []}], 'simplify_tolerance': 4.120516300408164e-05, 'sketch_entity_count': 96}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
